package org.treblereel.mcp.mcp.prefetch;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.treblereel.mcp.mcp.JavaEvidenceFixture;
import org.treblereel.mcp.mcp.TestReads;

/**
 * Apollo AQ-048 (Codex): asked where ReleaseManagementApi comes from and what to change instead of
 * the generated file, Codex grepped pom.xml and fetched the spec from the web; the prefetch named
 * only the bean implementing it.
 */
class GeneratedSourceFactTest {
    @TempDir Path root;

    @Test
    void aGeneratedSourceNamesItsPluginInputsAndImplementations() throws Exception {
        var db =
                JavaEvidenceFixture.index(
                        root,
                        Map.of(
                                "src/main/java/p/ReleaseController.java",
                                "package p; class ReleaseController implements gen.api.ReleaseApi {}",
                                "src/main/java/gen/api/ReleaseApi.java",
                                "package gen.api; public interface ReleaseApi {}"));
        Path module = Files.createDirectories(root.resolve("portal"));
        Path generated =
                root.resolve(
                        "portal/target/generated-sources/openapi/src/main/java/gen/api/ReleaseApi.java");
        Files.createDirectories(generated.getParent());
        Files.writeString(
                generated,
                "/**\n * NOTE: This class is auto generated by OpenAPI Generator (7.20.0).\n * Do not edit the class manually.\n */\npackage gen.api;\npublic interface ReleaseApi {}\n");
        Files.writeString(
                module.resolve("pom.xml"),
                """
                <project><properties><spec.url>https://example.invalid/api.yaml</spec.url><gen.version>7.20.0</gen.version></properties>
                <build><plugins><plugin><groupId>org.openapitools</groupId><artifactId>openapi-generator-maven-plugin</artifactId>
                <version>${gen.version}</version><executions><execution><phase>generate-sources</phase><configuration>
                <inputSpec>${spec.url}</inputSpec><generatorName>spring</generatorName>
                <output>${project.build.directory}/generated-sources/openapi</output></configuration></execution></executions>
                </plugin></plugins></build></project>
                """);
        var fact =
                TestReads.read(
                        db, reader -> GeneratedSourceFact.fact(reader, root, "gen.api.ReleaseApi"));
        assertEquals("generated_source", fact.path("kind").asText(), fact.toString());
        assertEquals(
                "portal/target/generated-sources/openapi/src/main/java/gen/api/ReleaseApi.java",
                fact.path("file").asText());
        assertTrue(
                fact.path("generator_note").toString().contains("OpenAPI Generator (7.20.0)"),
                fact.toString());
        String plugin = fact.path("generated_by_plugin").asText();
        assertTrue(
                plugin.contains("org.openapitools:openapi-generator-maven-plugin 7.20.0"), plugin);
        assertTrue(plugin.contains("portal/pom.xml"), plugin);
        String inputs = fact.path("plugin_inputs").toString();
        assertTrue(
                inputs.contains("inputSpec ${spec.url} = https://example.invalid/api.yaml"),
                inputs);
        assertTrue(inputs.contains("generatorName spring"), inputs);
        assertTrue(
                fact.path("implemented_by").toString().contains("p.ReleaseController"),
                fact.toString());
    }

    @Test
    void anOrdinaryNameHasNoGeneratedSource() throws Exception {
        var db = JavaEvidenceFixture.index(root, "package p; class A {}");
        assertNull(
                TestReads.read(
                        db, reader -> GeneratedSourceFact.fact(reader, root, "gen.api.Missing")));
    }
}
